#include <stdint.h>
#include "../Include/typedefs.h"
#include "../Include/keypad.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

#define SIZE 12

enum EVENT {
	READKEY = 0,
	SENDSTR = 1,
	NONE = 2,
};

void noEvent(void) {
	return;
}

void (*TaskTable[])(void) = {
		[READKEY] = KeyPad_Task,
		[NONE] = noEvent,
};

enum EVENT buffer[SIZE];
uint8_t write = 0;
uint8_t read = 0;
uint8_t count = 0;

void produce(enum EVENT event) {
	if(count == SIZE) {
		return;
	}

	buffer[write] = event;
	write = (write + 1) % SIZE;
	count++;
}

enum EVENT consume(void) {
	if(count == 0) {
		return NONE;
	}

	enum EVENT data = buffer[read];
	read = (read + 1) % SIZE;
	count--;
	return data;

}

int isFull(void) {
	return count == SIZE;
}

int isEmpty(void) {
	return count == 0;
}

void EXTI9_5_IRQHandler(void) {
	if(EXTI->PR & (1 << 5)) {
		EXTI->PR |= (1 << 5);
		produce(READKEY);
	}

	if(EXTI->PR & (1 << 6)) {
		EXTI->PR |= (1 << 6);
		produce(READKEY);
	}

	if(EXTI->PR & (1 << 7)) {
		EXTI->PR |= (1 << 7);
		produce(READKEY);
	}

	if(EXTI->PR & (1 << 8)) {
		EXTI->PR |= (1 << 8);
		produce(READKEY);
	}
}

int tx_head = 0;
int tx_tail = 0;
char tx_buffer[32];

void send_str(const char* str) {

	while(*str) {

		while(tx_head == tx_tail){

		}

		tx_head = (tx_head + 1) % 32;
		tx_buffer[tx_head] = *str;

		str++;
	}

	USART1->CR1 |= (1 << 7);
}

void USART1_IRQHandler(void) {
	if(USART1->SR & (1 << 7)) {
		if(tx_tail != tx_head){
			USART1->DR = tx_buffer[tx_tail];
			tx_tail = (tx_tail + 1) & 32;

		}
		else {
			USART1->CR1 &= ~(1 << 7);
		}
	}
}

int send = 1;

void dispatch(void) {
	while(1) {

		send_str("Test");
		for(volatile uint32_t i = 0; i < 1000000; i++);


		if(!isEmpty()) {
			enum EVENT event = consume();

			TaskTable[event]();

		}
	}
}

